with source as(select * from jsonb_to_recordset($rows$[{"exam_id": "summit-rossmoyne-mock-01", "question_number": 22, "stem": "A rectangular block is 5 unit cubes wide, 6 cubes deep and 4 cubes high. Its top and all four vertical sides are painted, but its bottom is not. How many unit cubes have paint on at least one face?", "explanation": "Count all cubes, then subtract those with no paint. There are 5 \u00d7 6 \u00d7 4 = 120 cubes. An unpainted cube must avoid both width sides, both depth sides and the top; it may touch the unpainted bottom. This leaves (5 \u2212 2) \u00d7 (6 \u2212 2) \u00d7 (4 \u2212 1) = 36 unpainted cubes. Subtract: 120 \u2212 36 = 84."}, {"exam_id": "summit-rossmoyne-mock-02", "question_number": 22, "stem": "A rectangular block is 6 unit cubes wide, 7 cubes deep and 5 cubes high. Its top and all four vertical sides are painted, but its bottom is not. How many unit cubes have paint on at least one face?", "explanation": "Count all cubes, then subtract those with no paint. There are 6 \u00d7 7 \u00d7 5 = 210 cubes. An unpainted cube must avoid both width sides, both depth sides and the top; it may touch the unpainted bottom. This leaves (6 \u2212 2) \u00d7 (7 \u2212 2) \u00d7 (5 \u2212 1) = 80 unpainted cubes. Subtract: 210 \u2212 80 = 130."}, {"exam_id": "summit-rossmoyne-mock-03", "question_number": 22, "stem": "A rectangular block is 4 unit cubes wide, 8 cubes deep and 3 cubes high. Its top and all four vertical sides are painted, but its bottom is not. How many unit cubes have paint on at least one face?", "explanation": "Count all cubes, then subtract those with no paint. There are 4 \u00d7 8 \u00d7 3 = 96 cubes. An unpainted cube must avoid both width sides, both depth sides and the top; it may touch the unpainted bottom. This leaves (4 \u2212 2) \u00d7 (8 \u2212 2) \u00d7 (3 \u2212 1) = 24 unpainted cubes. Subtract: 96 \u2212 24 = 72."}, {"exam_id": "summit-rossmoyne-mock-04", "question_number": 22, "stem": "A rectangular block is 5 unit cubes wide, 5 cubes deep and 4 cubes high. Its top and all four vertical sides are painted, but its bottom is not. How many unit cubes have paint on at least one face?", "explanation": "Count all cubes, then subtract those with no paint. There are 5 \u00d7 5 \u00d7 4 = 100 cubes. An unpainted cube must avoid both width sides, both depth sides and the top; it may touch the unpainted bottom. This leaves (5 \u2212 2) \u00d7 (5 \u2212 2) \u00d7 (4 \u2212 1) = 27 unpainted cubes. Subtract: 100 \u2212 27 = 73."}, {"exam_id": "summit-rossmoyne-mock-05", "question_number": 22, "stem": "A rectangular block is 6 unit cubes wide, 6 cubes deep and 5 cubes high. Its top and all four vertical sides are painted, but its bottom is not. How many unit cubes have paint on at least one face?", "explanation": "Count all cubes, then subtract those with no paint. There are 6 \u00d7 6 \u00d7 5 = 180 cubes. An unpainted cube must avoid both width sides, both depth sides and the top; it may touch the unpainted bottom. This leaves (6 \u2212 2) \u00d7 (6 \u2212 2) \u00d7 (5 \u2212 1) = 64 unpainted cubes. Subtract: 180 \u2212 64 = 116."}, {"exam_id": "summit-rossmoyne-mock-06", "question_number": 22, "stem": "A rectangular block is 4 unit cubes wide, 7 cubes deep and 3 cubes high. Its top and all four vertical sides are painted, but its bottom is not. How many unit cubes have paint on at least one face?", "explanation": "Count all cubes, then subtract those with no paint. There are 4 \u00d7 7 \u00d7 3 = 84 cubes. An unpainted cube must avoid both width sides, both depth sides and the top; it may touch the unpainted bottom. This leaves (4 \u2212 2) \u00d7 (7 \u2212 2) \u00d7 (3 \u2212 1) = 20 unpainted cubes. Subtract: 84 \u2212 20 = 64."}, {"exam_id": "summit-rossmoyne-mock-07", "question_number": 22, "stem": "A rectangular block is 5 unit cubes wide, 8 cubes deep and 4 cubes high. Its top and all four vertical sides are painted, but its bottom is not. How many unit cubes have paint on at least one face?", "explanation": "Count all cubes, then subtract those with no paint. There are 5 \u00d7 8 \u00d7 4 = 160 cubes. An unpainted cube must avoid both width sides, both depth sides and the top; it may touch the unpainted bottom. This leaves (5 \u2212 2) \u00d7 (8 \u2212 2) \u00d7 (4 \u2212 1) = 54 unpainted cubes. Subtract: 160 \u2212 54 = 106."}, {"exam_id": "summit-rossmoyne-mock-08", "question_number": 22, "stem": "A rectangular block is 6 unit cubes wide, 5 cubes deep and 5 cubes high. Its top and all four vertical sides are painted, but its bottom is not. How many unit cubes have paint on at least one face?", "explanation": "Count all cubes, then subtract those with no paint. There are 6 \u00d7 5 \u00d7 5 = 150 cubes. An unpainted cube must avoid both width sides, both depth sides and the top; it may touch the unpainted bottom. This leaves (6 \u2212 2) \u00d7 (5 \u2212 2) \u00d7 (5 \u2212 1) = 48 unpainted cubes. Subtract: 150 \u2212 48 = 102."}, {"exam_id": "summit-rossmoyne-mock-09", "question_number": 22, "stem": "A rectangular block is 4 unit cubes wide, 6 cubes deep and 3 cubes high. Its top and all four vertical sides are painted, but its bottom is not. How many unit cubes have paint on at least one face?", "explanation": "Count all cubes, then subtract those with no paint. There are 4 \u00d7 6 \u00d7 3 = 72 cubes. An unpainted cube must avoid both width sides, both depth sides and the top; it may touch the unpainted bottom. This leaves (4 \u2212 2) \u00d7 (6 \u2212 2) \u00d7 (3 \u2212 1) = 16 unpainted cubes. Subtract: 72 \u2212 16 = 56."}, {"exam_id": "summit-rossmoyne-mock-10", "question_number": 22, "stem": "A rectangular block is 5 unit cubes wide, 7 cubes deep and 4 cubes high. Its top and all four vertical sides are painted, but its bottom is not. How many unit cubes have paint on at least one face?", "explanation": "Count all cubes, then subtract those with no paint. There are 5 \u00d7 7 \u00d7 4 = 140 cubes. An unpainted cube must avoid both width sides, both depth sides and the top; it may touch the unpainted bottom. This leaves (5 \u2212 2) \u00d7 (7 \u2212 2) \u00d7 (4 \u2212 1) = 45 unpainted cubes. Subtract: 140 \u2212 45 = 95."}, {"exam_id": "summit-rossmoyne-mock-11", "question_number": 22, "stem": "A rectangular block is 6 unit cubes wide, 8 cubes deep and 5 cubes high. Its top and all four vertical sides are painted, but its bottom is not. How many unit cubes have paint on at least one face?", "explanation": "Count all cubes, then subtract those with no paint. There are 6 \u00d7 8 \u00d7 5 = 240 cubes. An unpainted cube must avoid both width sides, both depth sides and the top; it may touch the unpainted bottom. This leaves (6 \u2212 2) \u00d7 (8 \u2212 2) \u00d7 (5 \u2212 1) = 96 unpainted cubes. Subtract: 240 \u2212 96 = 144."}]$rows$::jsonb) as x(exam_id text,question_number int,stem text,explanation text))
